using System;

class Program
{
    static void Main()
    {
        // Read number of queries
        int q = int.Parse(Console.ReadLine());
        while (q-- > 0)
        {
            int val = int.Parse(Console.ReadLine());
            Console.WriteLine(val % 2 == 0 ? "EVEN" : "ODD");
        }
    }
}

